MYPY_HELP = [
    "# mypy - فاحص الأنواع الساكنة",
]

_MYPY_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _mypy_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in MYPY_CONSTS:
        return MYPY_CONSTS[word]
    if word in MYPY_FUNCS:
        return MYPY_FUNCS[word] + (open_paren or "")
    return match.group(0)


def MYPY_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _MYPY_TOKEN.sub(_mypy_replace, text)
